    'cdr_reports.help_body' => 'Надає детальний облік дзвінків (CDR) усіх вхідних/вихідних дзвінків, здійснених через AI PBX і кол-центр.',
    'cdr_reports.help_body2' => 'Кожен рядок — один дзвінок: у стовпці <b>Абонент</b> — транк, яким він надійшов, у стовпці <b>Набрано</b> — маршрут і, якщо дзвінок вийшов за межі АТС, транк і надісланий номер; <b>Відповів</b> — внутрішній номер, що прийняв дзвінок. <b>Напрямок</b>: вхідний, вихідний, внутрішній або транк-транк (надійшов через один транк і вийшов через інший без відповіді внутрішнього номера AiPBX). Розгорніть рядок, щоб побачити шлях переведених дзвінків. Фільтруйте за датою, станом, внутрішнім номером, пристроєм, напрямком і транком; прослуховуйте або завантажуйте записи.',
