    'asterisk_settings.rtp_section_title' => 'Налаштування RTP (медіа)',
    'asterisk_settings.rtp_help_body' => 'Визначає, який діапазон портів передає аудіо (RTP) і чи відхиляє Asterisk аудіо, що надходить з неочікуваного джерела. Цей файл (<code>/etc/asterisk/rtp.conf</code>) тепер генерується панеллю; ручні зміни на сервері буде втрачено під час наступного «Застосувати».',
