    'asterisk_settings.field_rtp_end' => 'Кінцевий порт RTP',
    'asterisk_settings.rtp_end_help' => 'Кінець діапазону. coturn (TURN-ретранслятор) використовує 13479-14999 — перекриття порушує аудіо WebRTC і відхиляється під час збереження.',
    'asterisk_settings.field_rtp_strict' => 'Strict RTP (strictrtp)',
    'asterisk_settings.rtp_strict_help' => 'Якщо увімкнено, Asterisk без попередження відкидає аудіо, що надходить з будь-якого джерела, крім визначеної віддаленої адреси/порту (захист від атак). Якщо віддалена АТС надсилає медіа з неочікуваного порту, це спричиняє тиху несправність «немає звуку» без слідів у журналі — для діагностики його можна тимчасово вимкнути.',
    'asterisk_settings.rtp_strict_yes' => 'Увімкнено (рекомендовано)',
    'asterisk_settings.rtp_strict_no' => 'Вимкнено (для діагностики)',
    'asterisk_settings.rtp_restart_warning' => 'Налаштування Strict RTP набуває чинності після «Застосувати». Однак зміна ДІАПАЗОНУ ПОРТІВ потребує повного перезапуску Asterisk — пул портів виділяється один раз під час завантаження модуля.',
