    'trunks.connection_mode_help' => 'За IP: віддалена сторона ідентифікується за IP-адресою, а її контакт залишається статичним — рекомендований режим для сторони з фіксованою IP в одній мережі. Вхідна реєстрація: віддалена сторона надсилає нам SIP REGISTER, і її адреса визначається з цієї реєстрації. Цей режим потребує імені користувача та пароля; віддалена сторона автентифікує ними і реєстрацію, і дзвінки.',
