    'sound_packs.tab' => 'Звукові пакети Asterisk',
    'sound_packs.title' => 'Офіційні звукові пакети Asterisk',
    'sound_packs.help_title' => 'Звукові пакети Asterisk',
    'sound_packs.help_body' => 'Завантажує та встановлює офіційні системні підказки та музику на утриманні Asterisk з <code>downloads.asterisk.org</code>. Кожен пакет — це одна мова в одному форматі; Asterisk відтворює формат, що відповідає кодеку дзвінка, а інакше перекодовує (g722 для G.722, ulaw/alaw для операторів).<br>- <strong>Основний:</strong> системні підказки, цифри, голосова пошта. <strong>Додатковий:</strong> додаткові підказки; спочатку має бути встановлено основний пакет тієї ж мови.<br>- <strong>Музика на утриманні (opsound):</strong> встановлюється в <code>/var/lib/asterisk/moh/opsound</code>; щоб її відтворювати, створіть клас MOH з назвою <strong>opsound</strong> на вкладці «Музика на утриманні».<br>- <strong>Türkçe (AiPBX):</strong> власні турецькі підказки AiPBX (реліз на GitHub, перевірка SHA256); мова за замовчуванням — турецька, тому їх вилучення вимкне системні підказки. Вилучення видаляє лише файли, встановлені пакетом.',
