    'ms_teams.guide_title' => 'Посібник з інтеграції Microsoft Teams',
    'ms_teams.guide_intro' => 'AiPBX може взаємодіяти з Microsoft Teams на двох різних рівнях:',
    'ms_teams.guide_dr_title' => '1. Direct Routing (SBC / SIP-транк):',
    'ms_teams.guide_dr_desc' => 'Дає змогу користувачам Teams здійснювати й отримувати внутрішні та зовнішні дзвінки безпосередньо з номеронабирача Teams на комп’ютері/мобільному. Потребує TLS (порт 5061), SRTP і дійсного публічного SSL-сертифіката (напр. Let\'s Encrypt).',
    'ms_teams.guide_webhook_title' => '2. Webhook і сповіщення в каналах:',
