    'system_update.page_title' => 'Оновлення системи',
    'system_update.help_title' => 'Як працює оновлення?',
    'system_update.help_body' => 'Оновлення спочатку створює резервну копію бази даних, налаштувань і конфігурації Asterisk, потім встановлює нову версію та перевіряє, що все працює. Якщо щось піде не так, автоматично відбувається повернення до попередньої версії. Під час оновлення Asterisk перезапускається: поточні дзвінки обриваються, тому оновлення не починається, доки є активні дзвінки. Його також можна запустити на сервері: <code>sudo aipbx-update</code>',
