    'certificates.help_title' => 'Посібник із сертифікатів',
    'certificates.help_body' => 'Портал (HTTPS), WebRTC TURNS і SIP-TLS/WSS використовують один сертифікат; зміни тут застосовуються одночасно до Apache, coturn і Asterisk. <b>Let\'s Encrypt</b> безкоштовний і поновлюється автоматично; домен має вказувати на цей сервер, а порт 80 має бути доступним з інтернету. Якщо Ваша організація має сертифікат, <b>завантажте його</b> (PEM або PFX); завантажені сертифікати не поновлюються автоматично, тому завантажте новий до закінчення строку дії. Із <b>самопідписаним</b> сертифікатом браузери показують попередження, а TURNS не працює в браузерах: дзвінки WebRTC за брандмауерами можуть бути без звуку.',
