    'queue_reports.help_title' => 'Посібник зі звітів черг',
    'queue_reports.help_body' => 'Кожен дзвінок, що потрапив у чергу, рахується один раз. <b>Прийняті</b>: з’єднані з оператором. <b>Втрачені</b>: абонент поклав слухавку під час очікування або минув час очікування черги. <b>Коротка відмова</b>: поклав слухавку протягом %d секунд; не враховується в рівні обслуговування. <b>Рівень обслуговування</b>: дзвінки, прийняті в межах цільового часу, від усіх дзвінків, окрім коротких відмов. <b>ASA</b>: середнє очікування прийнятих дзвінків. <b>AHT</b>: середня тривалість розмови. <b>Частка відповідей</b> (оператор): як часто оператор відповідав, коли черга його викликала. <b>Зворотний дзвінок</b>: втрачений дзвінок вважається опрацьованим, якщо на його номер пізніше зателефонували з внутрішнього номера або абонент зателефонував знову й отримав відповідь. Дані беруться з журналу черг Asterisk; звіт можна завантажити у форматі PDF або Excel.',
