    'ai_models.help_title' => 'Моделі ШІ на цьому сервері',
    'ai_models.help_body' => 'Запускає моделі ШІ на самій АТС: текст і звук ніколи не залишають сервер, без API-ключів та витрат. Спочатку встановіть <strong>локальне середовище виконання ШІ</strong> (близько 160 МБ на диску, завантажується один раз), потім завантажте потрібні моделі та прийміть їхню ліцензію. Завантажена модель використовує пам\'ять і процесор; тест швидкості показує, чи достатньо вона швидка на цьому сервері. Дзвінки зберігають пріоритет: служба працює з нижчим пріоритетом ЦП і обмеженням пам\'яті. Див. docs/local-ai.md.',
