    'ai_apps.help_title' => 'Програми ШІ зі своїми номерами',
    'ai_apps.help_body' => 'Програма ШІ відповідає на дзвінок, виконує своє завдання та передає дзвінок на призначення. Призначте їй внутрішній номер для прямого набору або виберіть її як призначення в IVR, вхідних маршрутах та часових умовах («Програма ШІ»). <strong>Оголошення зі змінними</strong>: текст, який зачитується голосовою моделлю цього сервера зі значеннями — {caller_number}, {caller_name}, {did} беруться з дзвінка, будь-які інші {name} — з вашої власної системи через адресу запиту. Зміни набувають чинності після натискання <strong>Застосувати</strong>.',
