    'ai_cloud.help_body' => 'Облікові записи хмарних постачальників ШІ в одному місці: мовлення, розпізнавання мовлення в текст, мовні моделі (Gemini, Gemma, GPT, Llama …) та ембедінги. Введіть ключ, перевірте його та виберіть для кожного завдання й мови потрібний рушій: локальна модель цього сервера чи хмарний постачальник. Безкоштовні тарифи позначені; використання за цей місяць відображається для кожного постачальника.',
