    'push.help_layer0' => '<strong>Рівень 0 (без залежностей - за замовчуванням):</strong> постійне з’єднання WSS, сумісна з Android 15 активна служба <code>specialUse</code> і стійкий до Doze сторожовий механізм <code>AlarmManager</code>, що її відновлює. Зовнішні сервіси не потрібні; дзвінки надходять навіть тоді, коли пристрій неактивний або екран вимкнено.',
    'push.help_layer1' => '<strong>Рівень 1 (необов’язковий - Google FCM):</strong> додаткова гарантія пробудження на пристроях OEM з агресивними обмеженнями батареї (Xiaomi, Huawei...) або коли користувач закрив застосунок. <em>Спрацьовує лише тоді, коли внутрішній номер не має активної реєстрації SIP, тож для зареєстрованих внутрішніх номерів затримки немає.</em>',
    'push.help_no_fcm' => 'Якщо Ви не хочете використовувати FCM, залиште постачальника <strong>«Локальний (без залежностей)»</strong>. Тоді мобільний застосунок взагалі не звертається до мережі Google.',
