    'mailtpl.invite_new.subject' => '[{brand}] Ваш обліковий запис створено - задайте пароль',
    'mailtpl.invite_new.body' => '<p>Вітаємо, {name}!</p>{mobile_section}<p>Ваш обліковий запис на АТС <strong>{brand}</strong> готовий. Щоб увійти, задайте пароль за допомогою кнопки нижче.</p>{account_details}{reset_button}<p>Якщо кнопка не працює, відкрийте це посилання: {reset_link}</p><p><em>Посилання для пароля дійсне 48 годин і спрацьовує один раз. Якщо ви не очікували цього листа, зверніться до системного адміністратора.</em></p>',
    'mailtpl.invite.subject' => '[{brand}] Ваше посилання для входу та пароля',
    'mailtpl.invite.body' => '<p>Вітаємо, {name}!</p>{mobile_section}<p>Ось нове посилання, щоб задати пароль для <strong>{brand}</strong>.</p>{account_details}{reset_button}<p>Якщо кнопка не працює, відкрийте це посилання: {reset_link}</p><p><em>Посилання для пароля дійсне 48 годин і спрацьовує один раз. Якщо ви його не запитували, зверніться до системного адміністратора.</em></p>',
    'mailtpl.password_reset.subject' => '[{brand}] Скидання пароля',
    'mailtpl.password_reset.body' => '<p>Вітаємо, {name}!</p><p>Для вашого облікового запису <strong>{username}</strong> запитано скидання пароля.</p>{reset_button}<p>Якщо кнопка не працює, відкрийте це посилання: {reset_link}</p><p><em>Посилання дійсне 30 хвилин. Якщо ви його не запитували, проігноруйте цей лист; ваш пароль не зміниться.</em></p>',
    'mailtpl.voicemail.subject' => 'Нове голосове повідомлення від {caller} ({duration})',
    'mailtpl.voicemail.body' => '<p>Вітаємо, {name}!</p><p>У скриньці голосової пошти <strong>{mailbox}</strong> нове повідомлення.</p><ul><li><strong>Від:</strong> {caller}</li><li><strong>Отримано:</strong> {date}</li><li><strong>Тривалість:</strong> {duration}</li></ul><p>Якщо запис додано, його можна прослухати просто тут. Також його можна прослухати на порталі ({portal_link}) або набравши *97.</p>',
    'mailtpl.fax_received.subject' => 'Отримано новий факс - {department} ({did})',
    'mailtpl.fax_received.body' => '<p>Отримано новий факс.</p><ul><li><strong>Підрозділ:</strong> {department}</li><li><strong>Номер факсу:</strong> {did}</li><li><strong>Від:</strong> {caller}</li><li><strong>Сторінок:</strong> {pages}</li><li><strong>Отримано:</strong> {date}</li></ul><p>Факс додається у форматі PDF, якщо цю функцію ввімкнено. Усі факси — у вхідних факсах: {portal_link}</p>',
    'mailtpl.fax_sent.subject' => 'Факс доставлено на {destination} (#{fax_id})',
