    'storage.help_title' => 'Де зберігаються файли чату',
    'storage.help_body' => '<p>Вкладення чату, їхні мініатюри та зображення груп за замовчуванням зберігаються на диску сервера (<code>/var/lib/aipbx/chat_files</code>). Із S3-сумісним сховищем (AWS S3, MinIO, Wasabi, Backblaze B2, Cloudflare R2 …) вони натомість потрапляють у бакет, і великі файли не навантажують АТС.</p><p>Завантаження й далі йдуть через службу чату, тож відкривати файли чату можуть лише його учасники; бакет може залишатися приватним. Файли, збережені до перемикання, і далі віддаються з диска, доки ви їх не перенесете. Налаштування бакета перевіряються перед збереженням.</p><p>Записи дзвінків, голосова пошта та факси залишаються на локальному диску.</p>',
