    'netsvc.help_title' => 'Мережеві служби',
    'netsvc.help_body' => 'Настільні телефони самі знаходять сервер автоналаштування, коли DHCP-сервер роздає його адресу (опція 66). DHCP і TFTP вмикаються окремо. Коли <strong>DHCP-сервер</strong> вимкнено, працює ваш власний DHCP-сервер: задайте на ньому опції, наведені нижче. Коли ввімкнено, AiPBX роздає адреси на одному інтерфейсі або VLAN. <strong>TFTP-сервер</strong> віддає завантажені вами boot-файли та прошивки. Конфігурація окремого телефону (з паролем SIP) завжди віддається через HTTPS, ніколи через TFTP.',
