    'web_widgets.help_body' => 'Віджет додає кнопку «Зателефонуйте нам» на будь-який сайт. Відвідувачі говорять з вами з браузера через WebRTC або залишають свій номер, і АТС їм передзвонює. Вставте однорядковий код на сайт (або в плагін WordPress) і після збереження натисніть <strong>Застосувати</strong>.',
